begin;
select plan(35);
select has_table('public','payment_intents','typed payment intents exist');
select has_table('public','financial_accounts','chart of accounts exists');
select has_table('public','financial_journals','journal headers exist');
select has_table('public','financial_postings','double-entry postings exist');
select has_table('public','refund_obligations','refund liabilities exist');
select has_table('public','provider_payables','provider payables exist');
select has_table('public','commission_obligations','commission liabilities exist');
select has_table('public','settlement_batches','settlement batches exist');
select has_table('public','financial_reconciliation_cases','reconciliation queue exists');
select has_table('public','external_deal_declarations','external deal declarations exist');
select has_table('public','cancellation_policy_versions','versioned cancellation policies exist');
select has_table('public','cancellation_policy_bands','cancellation bands exist');
select col_is_fk('public','platform_payment_orders','payment_intent_id','legacy order links to typed intent');
select has_function('public','calculate_cancellation_allocation',array['uuid','bigint','timestamp with time zone','timestamp with time zone'],'cancellation calculator exists');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,now()+interval '14 days',now())),100000::bigint,'14 days returns customer 100%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,now()+interval '5 days',now())),40000::bigint,'5 days returns customer 40%');
select is((select provider_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,now()+interval '5 days',now())),50000::bigint,'5 days returns provider 50%');
select is((select platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,now()+interval '5 days',now())),10000::bigint,'5 days returns platform 10%');
select is((select customer_minor+provider_minor+platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),99999,now()+interval '5 days',now())),99999::bigint,'cancellation rounding balances exactly');
select policies_are('public','financial_postings',array['financial_postings_finance_read'],'postings are finance-readable only');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-14 23:59+00','2027-01-01 00:00+00')),90000::bigint,'one minute below 14 days returns customer 90%');
select is((select platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-14 23:59+00','2027-01-01 00:00+00')),10000::bigint,'one minute below 14 days returns platform 10%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-07 00:00+00','2027-01-01 00:00+00')),90000::bigint,'exactly 6 days returns customer 90%');
select is((select platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-07 00:00+00','2027-01-01 00:00+00')),10000::bigint,'exactly 6 days returns platform 10%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-06 23:59+00','2027-01-01 00:00+00')),40000::bigint,'one minute below 6 days returns customer 40%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-05 00:00+00','2027-01-01 00:00+00')),40000::bigint,'exactly 4 days returns customer 40%');
select is((select provider_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-05 00:00+00','2027-01-01 00:00+00')),50000::bigint,'exactly 4 days returns provider 50%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-04 23:59+00','2027-01-01 00:00+00')),20000::bigint,'one minute below 4 days returns customer 20%');
select is((select provider_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-04 23:59+00','2027-01-01 00:00+00')),70000::bigint,'one minute below 4 days returns provider 70%');
select is((select customer_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-02 00:00+00','2027-01-01 00:00+00')),20000::bigint,'exactly 24 hours returns customer 20%');
select is((select provider_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-02 00:00+00','2027-01-01 00:00+00')),70000::bigint,'exactly 24 hours returns provider 70%');
select throws_ok($$select * from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-01 23:59+00','2027-01-01 00:00+00')$$,'P0001','An approved under-24-hour or no-show policy is required','under 24 hours requires a separately approved policy');
select is((select customer_minor+provider_minor+platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),25000,'2027-01-06 00:00+00','2027-01-01 00:00+00')),25000::bigint,'partial payment allocation balances exactly');
select is((select minimum_minutes_before_start from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),100000,'2027-01-07 00:00+00','2027-01-01 00:00+00')),8640,'exactly 6 days selects the 6-day band');
select is((select customer_minor+provider_minor+platform_minor from public.calculate_cancellation_allocation((select id from public.cancellation_policy_versions where code='KDM-STANDARD-SHORT' and version=1),0,'2027-01-07 00:00+00','2027-01-01 00:00+00')),0::bigint,'zero paid amount creates no allocation');
select * from finish();
rollback;
